[
  {
    "service": "RepositoryCrudService",
    "method": "requestApproval",
    "description": "Move a record into workflow approval: marks it pending and emits a `request-approval` workflow command. Requires the collection to have enableWorkflow=true.",
    "params": [
      {
        "name": "orgid",
        "type": "String",
        "description": "Org id.",
        "required": true
      },
      {
        "name": "datatype",
        "type": "String",
        "description": "Datatype.",
        "required": true
      },
      {
        "name": "id",
        "type": "String",
        "description": "Record sk.",
        "required": true
      }
    ],
    "returns": "The record (with updated workflow.status).",
    "group": "repository"
  },
  {
    "service": "RepositoryCrudService",
    "method": "approve",
    "description": "Approve a pending record via the workflow command bus.",
    "params": [
      {
        "name": "orgid",
        "type": "String",
        "description": "Org id.",
        "required": true
      },
      {
        "name": "datatype",
        "type": "String",
        "description": "Datatype.",
        "required": true
      },
      {
        "name": "id",
        "type": "String",
        "description": "Record sk.",
        "required": true
      }
    ],
    "returns": "true on success.",
    "group": "repository"
  },
  {
    "service": "RepositoryCrudService",
    "method": "reject",
    "description": "Reject a pending record via the workflow command bus.",
    "params": [
      {
        "name": "orgid",
        "type": "String",
        "description": "Org id.",
        "required": true
      },
      {
        "name": "datatype",
        "type": "String",
        "description": "Datatype.",
        "required": true
      },
      {
        "name": "id",
        "type": "String",
        "description": "Record sk.",
        "required": true
      }
    ],
    "returns": "true on success.",
    "group": "repository"
  },
  {
    "service": "RepositoryCrudService",
    "method": "isUnique",
    "description": "Check whether a value is unique on a given attribute. Honours collection schema property `uniqueScope` (single field or array) — when set, scopeValue must also be supplied. For `collection` datatype, also fuzzy-matches name.",
    "params": [
      {
        "name": "orgId",
        "type": "String",
        "description": "Org id.",
        "required": true
      },
      {
        "name": "datatype",
        "type": "String",
        "description": "Datatype to search.",
        "required": true
      },
      {
        "name": "attribute",
        "type": "String",
        "description": "Field name to check for uniqueness.",
        "required": true
      },
      {
        "name": "value",
        "type": "Object",
        "description": "Value to check.",
        "required": true
      },
      {
        "name": "scopeValue",
        "type": "Object",
        "description": "Required when the property has uniqueScope set.",
        "required": true
      }
    ],
    "returns": "sk of the existing record (truthy = NOT unique), or undefined when the value is unused.",
    "group": "repository"
  },
  {
    "service": "RepositoryCrudService",
    "method": "getPartial",
    "description": "Read a subset of fields off a record (provider-level projection).",
    "params": [
      {
        "name": "orgid",
        "type": "String",
        "description": "Org id.",
        "required": true
      },
      {
        "name": "datatype",
        "type": "String",
        "description": "Datatype.",
        "required": true
      },
      {
        "name": "id",
        "type": "String",
        "description": "Record sk.",
        "required": true
      },
      {
        "name": "fields",
        "type": "Array",
        "description": "Field names to include.",
        "required": true
      }
    ],
    "returns": "Partial record.",
    "group": "repository"
  },
  {
    "service": "RepositoryCrudService",
    "method": "findOne",
    "description": "Find a record by sk (must be a valid ObjectId). Optionally enriches type-specific related data.",
    "params": [
      {
        "name": "orgid",
        "type": "String",
        "description": "Org id.",
        "required": true
      },
      {
        "name": "datatype",
        "type": "String",
        "description": "Datatype.",
        "required": true
      },
      {
        "name": "id",
        "type": "String",
        "description": "Record sk (ObjectId).",
        "required": true
      },
      {
        "name": "enrich",
        "type": "Object",
        "description": "Whether to apply enrichment.",
        "required": false
      },
      {
        "name": "options",
        "type": "Object",
        "required": true
      }
    ],
    "returns": "BaseModel or null.",
    "group": "repository"
  },
  {
    "service": "RepositoryCrudService",
    "method": "findOneAnyId",
    "description": "Find a record by any natural identifier — username, email, slug, name, sku, number, or sk/_id (case-insensitive). Returns the first match; warns if multiple were found.",
    "params": [
      {
        "name": "orgId",
        "type": "String",
        "description": "Org id.",
        "required": true
      },
      {
        "name": "datatype",
        "type": "String",
        "description": "Datatype.",
        "required": true
      },
      {
        "name": "dataId",
        "type": "String",
        "description": "Identifier value.",
        "required": true
      },
      {
        "name": "options",
        "type": "Object",
        "description": "DataOptions including enrich flag.",
        "required": true
      }
    ],
    "returns": "BaseModel or undefined.",
    "group": "repository"
  },
  {
    "service": "RepositoryCrudService",
    "method": "findByAttribute",
    "description": "Find records matching attribute = value (or list all of a datatype when both omitted). Optionally enriches.",
    "params": [
      {
        "name": "orgid",
        "type": "String",
        "description": "Org id.",
        "required": true
      },
      {
        "name": "datatype",
        "type": "String",
        "description": "Datatype.",
        "required": true
      },
      {
        "name": "attribute",
        "type": "String",
        "description": "Field name.",
        "required": true
      },
      {
        "name": "value",
        "type": "String",
        "description": "Field value.",
        "required": true
      },
      {
        "name": "options",
        "type": "Object",
        "description": "DataOptions.",
        "required": true
      }
    ],
    "returns": "BaseModelDTO with matching records.",
    "group": "repository"
  },
  {
    "service": "RepositoryCrudService",
    "method": "findTimedData",
    "description": "Find records of one or more time-anchored datatypes (event/reservation/task/sf_subscription/schedule) overlapping a date range. Defaults to the next 30 days when endDate is omitted.",
    "params": [
      {
        "name": "orgid",
        "type": "String",
        "description": "Org id.",
        "required": true
      },
      {
        "name": "startDate",
        "type": "Object",
        "description": "ISO date or Date — defaults to now.",
        "required": true
      },
      {
        "name": "endDate",
        "type": "Object",
        "description": "ISO date or Date — defaults to startDate + 30 days.",
        "required": true
      },
      {
        "name": "datatypes",
        "type": "Object",
        "description": "Single datatype, comma string, or array. Defaults to all five.",
        "required": true
      },
      {
        "name": "options",
        "type": "Object",
        "description": "DataOptions.",
        "required": true
      }
    ],
    "returns": "Map keyed by datatype → BaseModelDTO.",
    "group": "repository"
  },
  {
    "service": "RepositoryCrudService",
    "method": "findPageData",
    "description": "Power site/storefront page queries: resolves either a specific record (by slug/name/sk) or builds a filtered listing across categories, tags, attribute filters (price ranges, keyword Elastic queries) for a \"collection-subSchema\" pair.",
    "params": [
      {
        "name": "orgId",
        "type": "String",
        "description": "Org id.",
        "required": true
      },
      {
        "name": "dataTypeTemp",
        "type": "String",
        "description": "\"collection-subSchema\" string (or just \"collection\").",
        "required": true
      },
      {
        "name": "dataId",
        "type": "String",
        "description": "Record id/slug for single-record fetch (skip filters when provided).",
        "required": true
      },
      {
        "name": "attributes",
        "type": "Object",
        "description": "Filter map (or JSON string) of attribute → value, including special \"price\" range.",
        "required": true
      },
      {
        "name": "keyword",
        "type": "String",
        "description": "Optional free-text keyword (routes through ElasticSearch query shape).",
        "required": true
      },
      {
        "name": "categories",
        "type": "Object",
        "description": "Single string, CSV, or array of category names.",
        "required": true
      },
      {
        "name": "tags",
        "type": "Object",
        "description": "Single string, CSV, or array of tag names.",
        "required": true
      },
      {
        "name": "options",
        "type": "Object",
        "description": "DataOptions.",
        "required": true
      }
    ],
    "returns": "BaseModelDTO of matching records.",
    "group": "repository"
  },
  {
    "service": "RepositoryCrudService",
    "method": "findRelated",
    "description": "Find related records (same datatype) by overlapping post.categories or post.tags of a primary record resolved through findOneAnyId.",
    "params": [
      {
        "name": "orgid",
        "type": "String",
        "description": "Org id.",
        "required": true
      },
      {
        "name": "datatype",
        "type": "String",
        "description": "Datatype.",
        "required": true
      },
      {
        "name": "anyId",
        "type": "String",
        "description": "Identifier of the primary record.",
        "required": true
      },
      {
        "name": "options",
        "type": "Object",
        "required": true
      }
    ],
    "returns": "BaseModelDTO of related records (or [] when primary has no taxonomy).",
    "group": "repository"
  },
  {
    "service": "RepositoryCrudService",
    "method": "find",
    "description": "Generic find: paginated query against a datatype with optional enrichment.",
    "params": [
      {
        "name": "orgid",
        "type": "String",
        "description": "Org id.",
        "required": true
      },
      {
        "name": "datatype",
        "type": "String",
        "description": "Datatype.",
        "required": true
      },
      {
        "name": "query",
        "type": "Object",
        "description": "Mongo or ES query body.",
        "required": true
      },
      {
        "name": "options",
        "type": "Object",
        "description": "DataOptions (page, pageSize, sort, enrich, ...).",
        "required": false
      }
    ],
    "returns": "BaseModelDTO.",
    "group": "repository"
  },
  {
    "service": "RepositoryCrudService",
    "method": "findExperts",
    "description": "Find experts in the configured shared org (`appmint-expert` collection).",
    "params": [
      {
        "name": "keyword",
        "type": "String",
        "description": "Search keyword.",
        "required": true
      }
    ],
    "returns": "BaseModelDTO of expert profiles.",
    "group": "repository"
  },
  {
    "service": "RepositoryCrudService",
    "method": "findAsset",
    "description": "Find shared assets (templates, components) — runs against the configured SHARED_ORG instead of the caller's org.",
    "params": [
      {
        "name": "datatype",
        "type": "String",
        "description": "Datatype in the shared org.",
        "required": true
      },
      {
        "name": "query",
        "type": "Object",
        "description": "Mongo query.",
        "required": true
      },
      {
        "name": "options",
        "type": "Object",
        "description": "DataOptions.",
        "required": true
      }
    ],
    "returns": "BaseModelDTO.",
    "group": "repository"
  },
  {
    "service": "RepositoryCrudService",
    "method": "searchAsset",
    "description": "Free-text search shared assets (delegates to search() against SHARED_ORG).",
    "params": [
      {
        "name": "datatype",
        "type": "String",
        "description": "Datatype.",
        "required": true
      },
      {
        "name": "keyword",
        "type": "Object",
        "description": "Search keyword.",
        "required": true
      },
      {
        "name": "query",
        "type": "Object",
        "description": "Optional Mongo filter.",
        "required": true
      },
      {
        "name": "options",
        "type": "Object",
        "description": "DataOptions.",
        "required": true
      }
    ],
    "returns": "BaseModelDTO.",
    "group": "repository"
  },
  {
    "service": "RepositoryCrudService",
    "method": "deleteAssets",
    "description": "Delete one or more shared/in-org assets. For component-style datatypes the underlying record is `flexdata`; for template datatypes the underlying record is `fileinfo` and the file payload is also removed.",
    "params": [
      {
        "name": "orgId",
        "type": "Object",
        "description": "Org id (overridden to SHARED_ORG for component/tag-template).",
        "required": true
      },
      {
        "name": "datatype",
        "type": "String",
        "description": "Asset datatype.",
        "required": true
      },
      {
        "name": "ids",
        "type": "Object",
        "description": "Single id or array.",
        "required": true
      }
    ],
    "returns": "true.",
    "group": "repository"
  },
  {
    "service": "RepositoryCrudService",
    "method": "updateAsset",
    "description": "Update an asset record — flexdata for component-style, fileinfo (and the underlying file payload) for template-style.",
    "params": [
      {
        "name": "orgId",
        "type": "Object",
        "description": "Org id.",
        "required": true
      },
      {
        "name": "datatype",
        "type": "String",
        "description": "Asset datatype.",
        "required": true
      },
      {
        "name": "id",
        "type": "Object",
        "description": "Asset id.",
        "required": true
      },
      {
        "name": "data",
        "type": "Object",
        "description": "Update payload.",
        "required": true
      }
    ],
    "returns": "void.",
    "group": "repository"
  },
  {
    "service": "RepositoryCrudService",
    "method": "getDataTypeCategories",
    "description": "Look up the `category` record whose name matches a datatype — used for taxonomy headers.",
    "params": [
      {
        "name": "orgId",
        "type": "String",
        "description": "Org id.",
        "required": true
      },
      {
        "name": "datatype",
        "type": "String",
        "description": "Datatype.",
        "required": true
      },
      {
        "name": "options",
        "type": "Object",
        "description": "DataOptions.",
        "required": true
      }
    ],
    "returns": "Category BaseModel or undefined.",
    "group": "repository"
  },
  {
    "service": "RepositoryCrudService",
    "method": "getTags",
    "description": "List the org's tag vocabulary from the `tag` collection, projected to sk/name/value, optionally filtered by a keyword matched anywhere in the tag name. Returns every match rather than a page — callers use this to populate tag pickers, and find() would otherwise cap it at 50. Uniqueness is enforced on the way in by addTag, so the list is already free of duplicates.",
    "params": [
      {
        "name": "orgId",
        "type": "String",
        "description": "Org id.",
        "required": true
      },
      {
        "name": "keyword",
        "type": "String",
        "description": "Optional search — matches anywhere in the tag name. Omit for the whole vocabulary.",
        "required": true
      }
    ],
    "returns": "BaseModelDTO of matching tag records, sorted by name, carrying only sk/name/value.",
    "group": "repository"
  },
  {
    "service": "RepositoryCrudService",
    "method": "addTag",
    "description": "Add a tag to the org's tag vocabulary. This is what keeps the collection free of duplicates: a tag whose name already exists (case-insensitive) is returned as-is instead of creating a second record, so reads never have to de-duplicate.",
    "params": [
      {
        "name": "orgId",
        "type": "String",
        "description": "Org id.",
        "required": true
      },
      {
        "name": "tag",
        "type": "Object",
        "description": "{ name (required), value? }. Name is stored lower-case; value defaults to it.",
        "required": true
      },
      {
        "name": "author",
        "type": "Object",
        "description": "Author label.",
        "required": false
      }
    ],
    "returns": "The created or already-existing tag record.",
    "group": "repository"
  },
  {
    "service": "RepositoryCrudService",
    "method": "findByTag",
    "description": "Provider-level multi-tag query.",
    "params": [
      {
        "name": "orgId",
        "type": "String",
        "description": "Org id.",
        "required": true
      },
      {
        "name": "datatype",
        "type": "String",
        "description": "Datatype.",
        "required": true
      },
      {
        "name": "tags",
        "type": "Array",
        "description": "Array of tag names.",
        "required": true
      },
      {
        "name": "options",
        "type": "Object",
        "description": "DataOptions.",
        "required": true
      }
    ],
    "returns": "BaseModelDTO.",
    "group": "repository"
  },
  {
    "service": "RepositoryCrudService",
    "method": "search",
    "description": "Free-text search via the provider. Falls back to find() when keyword is empty. Auto-recovers from \"text index required\" by calling fixCollection once and retrying.",
    "params": [
      {
        "name": "orgid",
        "type": "String",
        "description": "Org id.",
        "required": true
      },
      {
        "name": "datatype",
        "type": "String",
        "description": "Datatype to search (defaults to site_index when empty).",
        "required": true
      },
      {
        "name": "keyword",
        "type": "Object",
        "description": "Search keyword.",
        "required": true
      },
      {
        "name": "query",
        "type": "Object",
        "description": "Mongo filter to AND with the text query.",
        "required": true
      },
      {
        "name": "options",
        "type": "Object",
        "description": "DataOptions.",
        "required": true
      },
      {
        "name": "tries",
        "type": "Object",
        "description": "Internal retry counter.",
        "required": false
      }
    ],
    "returns": "BaseModelDTO.",
    "group": "repository"
  },
  {
    "service": "RepositoryCrudService",
    "method": "emitEvent",
    "description": "Insert a record bypassing all collection/workflow/schedule pre/post processing — used by bulk import, history rewrite, and migration.",
    "params": [
      {
        "name": "event",
        "type": "String",
        "required": true
      },
      {
        "name": "payload",
        "type": "Object",
        "required": true
      }
    ],
    "returns": "Inserted record (when returnObject=true) or provider-shaped result.",
    "group": "repository"
  },
  {
    "service": "RepositoryCrudService",
    "method": "createExtended",
    "description": "Custom create variants. Currently supports `create-page-from-template`: clones a page from the configured SHARED_ORG into the caller's org with a unique name/slug suffix.",
    "params": [
      {
        "name": "orgid",
        "type": "String",
        "description": "Org id.",
        "required": true
      },
      {
        "name": "createData",
        "type": "Object",
        "description": "{ data, action, options }.",
        "required": true
      },
      {
        "name": "created_by",
        "type": "Object",
        "description": "Author label.",
        "required": false
      }
    ],
    "returns": "Created record (delegates to create()).",
    "group": "repository"
  },
  {
    "service": "RepositoryCrudService",
    "method": "create",
    "description": "Create a record with full pipeline: collection lookup, datatype guards (company/reservation/event/user/customer use dedicated services), workflow + schedule materialisation, system events, Stripe/PayPal hookups for subscription plans. Drops duplicate calls (same payload) defensively.",
    "params": [
      {
        "name": "orgid",
        "type": "String",
        "description": "Org id.",
        "required": true
      },
      {
        "name": "data",
        "type": "Object",
        "description": "BaseModel to create. Must include datatype + non-empty data.",
        "required": true
      },
      {
        "name": "created_by",
        "type": "Object",
        "description": "Author label (defaults \"system\").",
        "required": false
      }
    ],
    "returns": "Created record with id resolved.",
    "group": "repository"
  },
  {
    "service": "RepositoryCrudService",
    "method": "update",
    "description": "Update a record with full pipeline: caller-source guards, history versioning + activity logging, workflow stage reset, schedule re-link, Stripe/PayPal subscription-plan upstream sync, COLLECTION_UPDATE event.",
    "params": [
      {
        "name": "orgid",
        "type": "String",
        "description": "Org id.",
        "required": true
      },
      {
        "name": "id",
        "type": "String",
        "description": "Record sk.",
        "required": true
      },
      {
        "name": "data",
        "type": "Object",
        "description": "BaseModel with mutated fields.",
        "required": true
      },
      {
        "name": "modified_by",
        "type": "Object",
        "description": "Author label (defaults \"system\").",
        "required": false
      }
    ],
    "returns": "Updated record.",
    "group": "repository"
  },
  {
    "service": "RepositoryCrudService",
    "method": "updatePartial",
    "description": "Provider-level partial update — sets the provided dotted-path key/value pairs without going through the full update pipeline.",
    "params": [
      {
        "name": "orgid",
        "type": "String",
        "description": "Org id.",
        "required": true
      },
      {
        "name": "datatype",
        "type": "Object",
        "description": "Datatype.",
        "required": true
      },
      {
        "name": "id",
        "type": "String",
        "description": "Record sk.",
        "required": true
      },
      {
        "name": "keyValuePair",
        "type": "Object",
        "description": "Map of dotted path → new value.",
        "required": true
      },
      {
        "name": "updateBy",
        "type": "String",
        "description": "Audit label (currently informational).",
        "required": true
      }
    ],
    "returns": "Provider-shaped update result.",
    "group": "repository"
  },
  {
    "service": "RepositoryCrudService",
    "method": "updateSystemFields",
    "description": "Restricted partial update for BaseModel wrapper fields (notes, stats, workflow, state, owner, requiredRole, post, style, name, etc.). Cannot touch `data` or `data.*`.",
    "params": [
      {
        "name": "orgid",
        "type": "String",
        "description": "Org id.",
        "required": true
      },
      {
        "name": "datatype",
        "type": "Object",
        "description": "Datatype.",
        "required": true
      },
      {
        "name": "id",
        "type": "String",
        "description": "Record sk.",
        "required": true
      },
      {
        "name": "keyValuePair",
        "type": "Object",
        "description": "Map of dotted path → new value. Top-level segment must be a whitelisted system field.",
        "required": true
      },
      {
        "name": "updateBy",
        "type": "String",
        "description": "Audit label.",
        "required": true
      }
    ],
    "returns": "Provider-shaped update result.",
    "group": "repository"
  },
  {
    "service": "RepositoryCrudService",
    "method": "publish",
    "description": "Publish a page or post: copies the source into the `published` collection and bumps state. Re-publishes when the content differs from the live copy; \"already published\" only when nothing changed. No-op for any other datatype.",
    "params": [
      {
        "name": "orgid",
        "type": "String",
        "description": "Org id.",
        "required": true
      },
      {
        "name": "datatype",
        "type": "String",
        "description": "page or post.",
        "required": true
      },
      {
        "name": "id",
        "type": "String",
        "description": "Record sk.",
        "required": true
      }
    ],
    "returns": "\"published\" / \"already published\".",
    "group": "repository"
